def min_cost_connect_points(points):
    n = len(points)
    edges = sorted((abs(x1 - x2) + abs(y1 - y2), i, j)
                   for i, (x1, y1) in enumerate(points)
                   for j, (x2, y2) in enumerate(points) if i < j)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = used = 0
    for w, i, j in edges:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj
            total += w
            used += 1
            if used == n - 1:
                break
    return total

def min_cost_connect_points(points):
    n = len(points)
    seen, heap, total = set(), [(0, 0)], 0
    while len(seen) < n:
        w, i = heapq.heappop(heap)
        if i in seen:
            continue
        seen.add(i)
        total += w
        xi, yi = points[i]
        for j, (xj, yj) in enumerate(points):
            if j not in seen:
                heapq.heappush(heap, (abs(xi - xj) + abs(yi - yj), j))
    return total
